from typing import Iterable, Optional

# Initialize variables to store the indexed data
term_dict = {}
postings = {}
doc_lens = []
avg_doc_len = 0

# Iterate over the input array in batches
for i in range(0, len(array), batch_size):
    batch = array[i:i + batch_size]

    # Tokenize each string in the batch using the specified tokenizer
    tokens = [tokenizer(string) for string in batch]

    # Iterate over the tokens in the batch
    for token in set(tokens):
        # If the token is not in the term dictionary, add it
        if token not in term_dict:
            term_dict[token] = len(term_dict)

        # Update the postings for the token in the current batch
        for j, string in enumerate(batch):
            if token in tokens[j]:
                if token not in postings:
                    postings[token] = []
                postings[token].append((j + 1, len(string.split()) + 1))

    # Update the document lengths for the current batch
    doc_lens.extend([len(string.split()) for string in batch])

# Calculate the average document length
avg_doc_len = np.mean(doc_lens)

# Create a new instance of SearchArray with the indexed data
return cls(term_dict, postings, doc_lens, avg_doc_len)

